const e="prerelease-dacd56f8",t=["1b","2a"],a={tests:{under18:{questions:46,pass:38},adult:{questions:36,pass:30}},areas:{signs_and_signals:{under18:16,adult:13},roadway_rules:{under18:11,adult:9},driving_safety:{under18:7,adult:5},legal_and_liability:{under18:3,adult:3},california_specific:{under18:6,adult:5},environment:{under18:3,adult:1}}},o=JSON.parse(`[{"id":"q-1b-001","fact_id":"s4-10","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"Which of these changes to your license record needs the DMV's own change process, not just a quick notice?","options":["Getting a new phone number","Switching to a different car insurer","Moving to a new apartment in the same city","Changing your legal name"],"correct":3},{"id":"q-1b-002","fact_id":"s4-10","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"Marisol marries and takes a new surname. Her license still shows the old one. What should she do?","options":["Start the DMV's name-change process with her documents","Tell her insurer, which updates the DMV for her","Wait until the license expires and renew it","Keep driving, since the photo still looks like her"],"correct":0},{"id":"q-1b-003","fact_id":"s4-10","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Two license updates: a new home address, and a changed legal name. Which statement is right?","options":["Both are only done when the license is renewed","The address is reported within a set number of days; the name goes through the DMV's change process","The name change is quick, but the address needs a new test","Both can be ignored if the card is still valid"],"correct":1},{"id":"q-1b-004","fact_id":"s6_p11_roadway-008","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"On a narrow mountain road, two cars meet nose to nose. Which one has the right of way?","options":["The one going downhill","The faster one","The one that arrived first","The one going uphill"],"correct":3},{"id":"q-1b-005","fact_id":"s6_p11_roadway-008","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are driving down a one-lane mountain road. A car comes up toward you and there is no room to pass. What should you do?","options":["Squeeze past on the shoulder edge","Flash your lights and stay put","Wait for the other driver to reverse","Back up to a place where it can pass"],"correct":3},{"id":"q-1b-006","fact_id":"s6_p11_roadway-008","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which driver gives way on a steep, one-lane road with no room to pass?","options":["The driver going uphill","The driver going downhill","Both back up a little each","The driver with the heavier vehicle, whichever way it faces"],"correct":1},{"id":"q-1b-007","fact_id":"s6_p11_run2-025","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A slow vehicle is climbing a mountain pass with cars lined up behind it. Where should it let them by?","options":["In the middle of the lane, by slowing more","On the next blind bend","Nowhere; it has the right of way","At a marked turnout, when it is safe"],"correct":3},{"id":"q-1b-008","fact_id":"s6_p11_run2-025","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive a camper up a winding grade. Six cars follow you. You see a turnout ahead. What is best?","options":["Ignore them; the speed limit is your only duty","Speed up until they stop following","Stop in the lane and wave them round","Pull into the turnout when safe and let them pass"],"correct":3},{"id":"q-1b-009","fact_id":"s6_p11_run2-025","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for mountain roads?","options":["Uphill cars give way to all downhill cars","Uphill cars back up; slow cars never stop","Slow cars wait for the first straight section","Downhill cars back up; slow vehicles use turnouts when safe"],"correct":3},{"id":"q-1b-010","fact_id":"s6_p11_run3-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the closest you may leave your car to a fire hydrant?","options":["10 feet away","20 feet away","15 feet away","5 feet away"],"correct":2},{"id":"q-1b-011","fact_id":"s6_p11_run3-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You need a quick errand and see a space with a hydrant at the near end. Roughly how much clear space must be left?","options":["About two car lengths","None if you stay in the car","About one car length","About half a car length"],"correct":2},{"id":"q-1b-012","fact_id":"s6_p11_run3-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which distance goes with which place? Hydrant 15 feet, crosswalk 20 feet.","options":["Hydrant 20, crosswalk 15","Both are 20 feet","Hydrant 15, crosswalk 20","Both are 15 feet"],"correct":2},{"id":"q-1b-013","fact_id":"s6_p11_run3-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How far back from a crosswalk's approach side must you stay when you park?","options":["10 feet","30 feet","5 feet","20 feet"],"correct":3},{"id":"q-1b-014","fact_id":"s6_p11_run3-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A corner has no painted lines, but people clearly cross there. You are looking for a spot on the side you approach from. Which is OK?","options":["A spot at the corner during daylight only","A spot right at the corner, if you stay in the car","A spot 10 feet back from the corner","A spot 25 feet back from the corner"],"correct":3},{"id":"q-1b-015","fact_id":"s6_p11_run3-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which stops are OK to park at?","options":["Inside the 20-foot zone with hazard lights on","25 feet back from an unmarked crosswalk","Directly on the approach side of a crosswalk","12 feet from a fire hydrant"],"correct":1},{"id":"q-1b-016","fact_id":"s6_p11_run3-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At an intersection with no painted crosswalk, a person steps off the curb. Who has the right of way?","options":["The pedestrian, as at a painted crosswalk","Whoever is first to the corner","The driver, since there is no paint","The larger vehicle"],"correct":0},{"id":"q-1b-017","fact_id":"s6_p11_run3-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You turn onto a quiet side street with no crosswalk lines. A woman is already crossing. What do you do?","options":["Go ahead because there is no marking","Honk so she hurries","Drive behind her once she passes your bumper","Stop and let her finish crossing"],"correct":3},{"id":"q-1b-018","fact_id":"s6_p11_run3-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement is true about crosswalks?","options":["Marked and unmarked crosswalks give people the same priority","Unmarked crosswalks only matter at night","Painted lines are required before a driver must yield","Only school crosswalks give people priority"],"correct":0},{"id":"q-1b-019","fact_id":"s6_p11_run3-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What must you do when a person crosses with a white cane or a guide dog?","options":["Sound your horn to warn them","Move slowly past them","Wait only if the signal is red","Yield and let them cross"],"correct":3},{"id":"q-1b-020","fact_id":"s6_p11_run3-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are waiting to turn right. A man with a white cane steps into the crosswalk. What now?","options":["Tap the horn once so he knows you are waiting","Creep forward to show you are there","Turn once he passes your front bumper","Stay stopped until he has crossed"],"correct":3},{"id":"q-1b-021","fact_id":"s6_p11_run3-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which driver is in the wrong?","options":["One who waits until a cane user has fully crossed","One who stops for a guide-dog user in a crosswalk","One who honks at a guide-dog team to hurry them","One who yields to a woman with a white cane"],"correct":2},{"id":"q-1b-022","fact_id":"s6_p11_run3-008","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a white curb mean?","options":["Loading goods only","Passenger pick-up and drop-off only","Parking for disabled drivers only","Parking for short errands"],"correct":1},{"id":"q-1b-023","fact_id":"s6_p11_run3-008","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You need to leave your car for an hour outside a post office. The only open space is next to a white curb. What now?","options":["Use it if you pay the meter","Use it, since the post office is a public building","Use it if you leave the engine running","Find another space, because white curbs are for brief passenger stops"],"correct":3},{"id":"q-1b-024","fact_id":"s6_p11_run3-008","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Match colors to purposes. Which line is right?","options":["Red: loading. Blue: passengers","White: loading. Yellow: passengers","White: passengers. Yellow: loading","White: time-limited parking. Green: loading"],"correct":2},{"id":"q-1b-025","fact_id":"s6_p11_run3-009","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a green curb mean?","options":["Parking is for buses","Parking is free all day","Parking is limited to a posted time","Only electric cars may stop"],"correct":2},{"id":"q-1b-026","fact_id":"s6_p11_run3-009","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You pull up at a green curb to run into a shop. How do you learn how long you may stay?","options":["Ask the shop owner to tell you the rule","Assume it is 24 hours unless told otherwise","Read the sign posted at that curb","Leave a note on the dash with your return time"],"correct":2},{"id":"q-1b-027","fact_id":"s6_p11_run3-009","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which curb allows ordinary short-term parking, with the limit shown on a sign?","options":["White","Red","Yellow","Green"],"correct":3},{"id":"q-1b-028","fact_id":"s6_p11_run3-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What may you do at a yellow curb?","options":["Park for the whole day","Wait for a friend with the engine off","Park if you have a disabled plate","Load or unload during the posted hours"],"correct":3},{"id":"q-1b-029","fact_id":"s6_p11_run3-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A shop assistant pulls up at a yellow curb to unload boxes. Is that fine?","options":["No, only trucks may use yellow curbs","Yes, during the hours posted for loading","Yes, but she must also buy a permit","No, yellow means stopping is banned"],"correct":1},{"id":"q-1b-030","fact_id":"s6_p11_run3-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which is correct?","options":["Red means loading is allowed","Yellow means loading, red means no stopping","Green means loading during the posted hours","Yellow means no stopping at any time"],"correct":1},{"id":"q-1b-031","fact_id":"s6_p11_run3-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How long may you stop at a white curb?","options":["As long as a passenger stays in the car","Ten minutes","As long as the engine is running","Just the time it takes for people to get in or out"],"correct":3},{"id":"q-1b-032","fact_id":"s6_p11_run3-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drop off your grandmother at a white curb. She asks you to wait while she goes in for an appointment. What should you do?","options":["Leave the white curb and park somewhere legal","Wait there with the engine off","Stay in the driver's seat the whole time","Wait there with your hazards on"],"correct":0},{"id":"q-1b-033","fact_id":"s6_p11_run3-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which action at a white curb is allowed?","options":["Loading a van for twenty minutes","Letting a passenger step out, then driving on","Parking with a time-limit ticket","Leaving the car while you shop"],"correct":1},{"id":"q-1b-034","fact_id":"s6_p11_run3-016","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A car ahead has stopped at a crosswalk. What must you not do?","options":["Pass it","Look for pedestrians","Slow down","Stop behind it"],"correct":0},{"id":"q-1b-035","fact_id":"s6_p11_run3-016","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are in the left lane. The car in the right lane has stopped just before a crosswalk, and you cannot see why. What do you do?","options":["Slow slightly and pass if nobody is visible","Move over behind it and honk","Stop too, since a person may be crossing","Drive past it at the same speed"],"correct":2},{"id":"q-1b-036","fact_id":"s6_p11_run3-016","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which driver is right at a crosswalk where the car ahead is stopped?","options":["The one who waits until it moves","The one who passes on the right","The one who tailgates to hurry it up","The one who passes if the road looks empty"],"correct":0},{"id":"q-1b-037","fact_id":"s6_p11_run3-017","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What does a red curb mean?","options":["No parking, but stopping is OK","No stopping, standing or parking","Parking for a limited time","Parking for emergency vehicles only"],"correct":1},{"id":"q-1b-038","fact_id":"s6_p11_run3-017","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are late and want to dash into a shop for 30 seconds. The only space is a red curb. What is the right call?","options":["Stop with your hazards on","Do not stop there, even for 30 seconds","Stop if you stay in the car","Stop if no traffic officer is around"],"correct":1},{"id":"q-1b-039","fact_id":"s6_p11_run3-017","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair describes red and white curbs correctly?","options":["Red: quick passenger stop. White: no stopping","Red: no stopping. White: quick passenger stop","Red: loading. White: parking","Red: parking. White: no stopping"],"correct":1},{"id":"q-1b-040","fact_id":"s6_p11_run3-018","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Who may use a blue curb space?","options":["Drivers with a disabled person's permit","Anyone for ten minutes","Drivers with a short-trip ticket","Delivery vehicles"],"correct":0},{"id":"q-1b-041","fact_id":"s6_p11_run3-018","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive a friend who has a valid disabled placard, but you are the one who will park. The only open space is blue. Can you use it while she is in the car?","options":["Yes, if you have your own license","No, only she may use a blue space","Yes, even if she gets out first","Yes, with the permit displayed and her in the vehicle"],"correct":3},{"id":"q-1b-042","fact_id":"s6_p11_run3-018","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Blue and white curbs differ. Which is right?","options":["White is for disabled permit holders","Both mean no stopping","Blue is for anyone stopping briefly","Blue is for permit holders, white is for quick passenger stops"],"correct":3},{"id":"q-1b-043","fact_id":"s6_p11_run3-019","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How early must you start signalling before a turn?","options":["Only when other cars are close","10 feet before the turn","At the moment you turn","At least 100 feet before the turn"],"correct":3},{"id":"q-1b-044","fact_id":"s6_p11_run3-019","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are about to turn right, and the corner is about 30 feet ahead. When should your signal have started?","options":["Only if a car is behind you","About 70 feet earlier, to cover the last 100 feet","Right now","After you reach the corner"],"correct":1},{"id":"q-1b-045","fact_id":"s6_p11_run3-019","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"What do the numbers 100 feet and 15 feet describe?","options":["Crosswalk clearance and hydrant clearance","Turn-signal distance and hydrant clearance","Hydrant clearance and alley speed","Alley length and signal distance"],"correct":1},{"id":"q-1b-046","fact_id":"s7_p11_run2-015","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the speed limit in a residential area unless a sign says otherwise?","options":["15 mph","45 mph","35 mph","25 mph"],"correct":3},{"id":"q-1b-047","fact_id":"s7_p11_run2-015","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You turn into a neighborhood with houses and children's bikes on the lawns. No speed sign is visible. How fast may you go?","options":["30 mph at most","25 mph at most","20 mph is the legal minimum","Any speed that feels safe"],"correct":1},{"id":"q-1b-048","fact_id":"s7_p11_run2-015","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which limits are right when nothing else is posted?","options":["Residential 15, alley 25","Both 15","Residential 25, alley 15","Both 25"],"correct":2},{"id":"q-1b-049","fact_id":"s7_p11_run2-017","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How fast may you drive down an alley when no other limit is posted?","options":["10 mph","15 mph","25 mph","20 mph"],"correct":1},{"id":"q-1b-050","fact_id":"s7_p11_run2-017","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You cut through a narrow alley behind a row of shops. A delivery truck is unloading ahead. How fast should you be going, at most?","options":["25 mph","Whatever the traffic allows","15 mph","35 mph"],"correct":2},{"id":"q-1b-051","fact_id":"s7_p11_run2-017","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which place has the lowest default speed limit?","options":["A school road","A residential street","An alley","A quiet cul-de-sac"],"correct":2},{"id":"q-1b-052","fact_id":"s7_p11_run3-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"A person is crossing ahead of you at a crosswalk. What must you do?","options":["Slow down or stop for them","Honk to warn them","Speed up to clear it before they step out","Keep your speed and steer round"],"correct":0},{"id":"q-1b-053","fact_id":"s7_p11_run3-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You approach a corner with no painted lines. A child is beginning to cross. What do you do?","options":["Flash your lights and drive on","Speed up to pass before the child gets there","Slow down and stop if needed","Keep going since there is no paint"],"correct":2},{"id":"q-1b-054","fact_id":"s7_p11_run3-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does a crosswalk driver's duty change at night?","options":["It is the same: slow or stop for people","It only applies when streetlights are on","It ends when the sun sets","It is only for marked crosswalks at night"],"correct":0},{"id":"q-1b-055","fact_id":"s7_p11_run3-013","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which action by a pedestrian is NOT allowed?","options":["Stepping into the road so close to a moving car that it cannot stop","Crossing at a marked crosswalk","Waiting at the curb for a gap","Crossing once the traffic has stopped"],"correct":0},{"id":"q-1b-056","fact_id":"s7_p11_run3-013","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A man runs into the crosswalk right in front of your moving car, far too close for you to stop. Who has broken a rule?","options":["The pedestrian, who entered the path too close","You, for not stopping in time","Neither, because it was a short distance","Nobody, because crosswalks give priority"],"correct":0},{"id":"q-1b-057","fact_id":"s7_p11_run3-013","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement about pedestrian rights is right?","options":["Pedestrians only lose priority outside cities","Drivers always give way, with no exceptions","Pedestrians may enter the road whenever they want","Pedestrians have priority in crosswalks but must not step in front of a car that cannot stop"],"correct":3},{"id":"q-1b-058","fact_id":"s7_p11_run3-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What must a pedestrian NOT do in a crosswalk?","options":["Look both ways before crossing","Cross at a steady walk","Use the crosswalk at night","Stop or delay traffic for no good reason"],"correct":3},{"id":"q-1b-059","fact_id":"s7_p11_run3-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A man stands in the middle of a crosswalk chatting on his phone while cars wait. What does the rule say?","options":["Drivers must wait as long as he likes","He has no duties in a crosswalk","He should not hold up traffic without reason","Drivers may drive round him"],"correct":2},{"id":"q-1b-060","fact_id":"s7_p11_run3-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which is true about crosswalks?","options":["Drivers must yield, and pedestrians must not hold up traffic needlessly","Only drivers have duties","People may stay as long as they like","Cars may always pass people who are slow"],"correct":0},{"id":"q-1b-061","fact_id":"signs-015","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a red octagon with a stop sign on it. What does it warn about?","options":["You must stop here right now","Traffic will merge from the right","A stop sign is coming up, so slow down","A school zone is ahead"],"correct":2},{"id":"q-1b-062","fact_id":"signs-015","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are rolling down a country road and see this diamond with a stop sign symbol. The road ahead is clear. What is best?","options":["Wait to slow until you see cars stopped ahead","Keep your speed until you see the stop line","Change lanes to avoid the junction","Ease off the gas and get ready to stop"],"correct":3},{"id":"q-1b-063","fact_id":"signs-016","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond with a downward triangle inside it warns of what?","options":["A one-way street begins","A yield sign is ahead","A no-parking zone starts","A stop sign is ahead"],"correct":1},{"id":"q-1b-064","fact_id":"signs-016","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Both a stop-ahead and a yield-ahead sign are yellow diamonds. How do you tell them apart?","options":["By the number of lanes","By the road surface","By the size of the sign post","By the symbol in the middle"],"correct":3},{"id":"q-1b-065","fact_id":"signs-017","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows red, yellow and green lights. What does it mean?","options":["Signals are broken ahead","A railroad crossing is ahead","A traffic signal is ahead","You must stop at the next light"],"correct":2},{"id":"q-1b-066","fact_id":"signs-017","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"It is dusk and you see the signal-ahead sign on a long straight road. You cannot yet see the light. What do you do?","options":["Ignore it until you can see the lights","Stop on the spot","Speed up to make the green","Watch for the signal and be ready to slow"],"correct":3},{"id":"q-1b-067","fact_id":"signs-018","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond has an arrow that bends to the right. What is ahead?","options":["A one-way street to the right","A right turn only lane","A right-hand exit","The road bends right"],"correct":3},{"id":"q-1b-068","fact_id":"signs-018","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a right-bend sign at a high speed. What should you do?","options":["Move to the left lane edge and speed up","Brake hard in the middle of the curve","Slow down before the curve","Stay at your speed because the road is dry"],"correct":2},{"id":"q-1b-069","fact_id":"signs-019","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond has an arrow that bends to the left. What does it warn of?","options":["A left turn lane","A left-hand merge","A bend in the road to the left","Traffic going the other way"],"correct":2},{"id":"q-1b-070","fact_id":"signs-019","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which sign matches 'the road bends left ahead'?","options":["A diamond with a snake-like line","A diamond with two arrows pointing apart","A diamond with a right-curving arrow","A diamond with a left-curving arrow"],"correct":3},{"id":"q-1b-071","fact_id":"signs-020","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows an S-shaped arrow. What does it mean?","options":["Several bends in a row","A sharp left, then a right turn lane","A slippery road","A stretch of road works"],"correct":0},{"id":"q-1b-072","fact_id":"signs-020","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the winding-road sign at the start of a hill. What should your speed plan be?","options":["Hold your speed since the road is paved","Use the middle of the road to cut the curves","Slow to a pace that handles each bend","Take the first bend fast and slow later"],"correct":2},{"id":"q-1b-073","fact_id":"signs-021","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a side road joining a main road. What should you expect?","options":["A crossroad","Another lane joins from the side","A traffic signal","Your lane ends"],"correct":1},{"id":"q-1b-074","fact_id":"signs-021","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are on a main road and see the merging-traffic sign. A car appears on the on-ramp beside you. What is a good move?","options":["Speed up so it cannot enter","Brake hard in your lane","Be ready to make room for it","Honk so it waits"],"correct":2},{"id":"q-1b-075","fact_id":"signs-022","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows two lanes narrowing to one. What does it warn of?","options":["Your lane ends ahead","A new lane begins","Traffic from the side","A road splitting into two"],"correct":0},{"id":"q-1b-076","fact_id":"signs-022","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Merging-traffic and lane-ends signs both show lines joining. What is the difference for you?","options":["Both mean the same thing","Merging means you must stop","Lane ends means your lane gets wider","Lane ends means your own lane stops; merging means others join yours"],"correct":3},{"id":"q-1b-077","fact_id":"signs-023","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows two arrows pointing in opposite directions. What does it say?","options":["Traffic goes both ways ahead","The road splits ahead","A U-turn is allowed","Passing is allowed here"],"correct":0},{"id":"q-1b-078","fact_id":"signs-023","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You leave a divided road and see the two-way-traffic sign. What changes for you?","options":["Oncoming cars now share the road, so stay in your own lane","The road is now one-way, so any lane will do","The speed limit no longer applies","Cars from the left must give way to you"],"correct":0},{"id":"q-1b-079","fact_id":"signs-024","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A fluorescent yellow-green diamond shows a walking figure. What does it tell you?","options":["A school is ahead","Bicycles may cross here","People may cross here","A pedestrian bridge is ahead"],"correct":2},{"id":"q-1b-080","fact_id":"signs-024","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which color is used for pedestrian, bicycle and school crossing signs?","options":["Fluorescent yellow-green","Plain white","Orange","Red"],"correct":0},{"id":"q-1b-081","fact_id":"signs-025","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a plus sign. What is ahead?","options":["A railroad crossing","A lane merge","A hospital","A road crosses yours"],"correct":3},{"id":"q-1b-082","fact_id":"signs-025","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the crossroad-ahead sign on a quiet road. What is wise?","options":["Look both ways before you reach it","Stop 100 feet before it","Assume nobody can come from the sides","Speed up so you clear it fast"],"correct":0},{"id":"q-1b-083","fact_id":"signs-026","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a car with wavy skid marks behind it. What is the warning?","options":["A speed bump is ahead","The road may be slippery when wet","The road is closed","A sharp bend is ahead"],"correct":1},{"id":"q-1b-084","fact_id":"signs-026","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"Rain is falling and you see this sign. A red light ahead is turning. How do you slow?","options":["Brake as hard as you can","Ease off and brake gently","Downshift hard and release the clutch","Steer sharply to the side"],"correct":1},{"id":"q-1b-085","fact_id":"signs-027","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a road with a barrier in the middle, splitting into two. What does it warn of?","options":["A lane ends","A divided highway begins","Two-way traffic ends","A bridge ahead"],"correct":1},{"id":"q-1b-086","fact_id":"signs-027","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You pass the divided-highway sign. Where should you drive?","options":["Cross the median to save time","Keep to the right of the median","Drive on the left of the median","Stop at the median"],"correct":1},{"id":"q-1b-087","fact_id":"signs-028","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a leaping deer. What should you watch for?","options":["A forest ranger","Animals crossing the road","A hunting zone","A nature park exit"],"correct":1},{"id":"q-1b-088","fact_id":"signs-028","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"At dusk you see the animal-crossing sign. What should you do?","options":["Drive faster to get through quickly","Slow down and scan the sides of the road","Keep your eyes on the lane ahead only","Use your horn constantly"],"correct":1},{"id":"q-1b-089","fact_id":"signs-029","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"An orange diamond with a worker symbol means what?","options":["A flagger is behind you","A detour ends","A school zone begins","Road work is ahead"],"correct":3},{"id":"q-1b-090","fact_id":"signs-029","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which color of diamond means a work zone?","options":["Yellow-green","Blue","Orange","Red"],"correct":2},{"id":"q-1b-091","fact_id":"signs-030","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow circle with a black X and two letters R means what?","options":["A road crossing is ahead","Trains are always on the road","A railroad crossing is ahead","A railway station is near"],"correct":2},{"id":"q-1b-092","fact_id":"signs-030","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the round railroad warning sign. The road ahead is clear. What do you do?","options":["Stop on the tracks to look","Slow down and be ready to stop","Speed up to beat any train","Change lanes close to the tracks"],"correct":1},{"id":"q-1b-093","fact_id":"signs-031","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A fluorescent yellow-green pentagon (five sides) shows two children walking. What does it warn of?","options":["A school crossing","A hospital","A bus stop","A playground"],"correct":0},{"id":"q-1b-094","fact_id":"signs-031","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which shape is only used for the school crossing sign?","options":["Pentagon","Circle","Diamond","Octagon"],"correct":0},{"id":"q-1b-095","fact_id":"signs-032","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow sign shaped like a pennant (a long triangle) sits on the left side of the road. What does it mean?","options":["A parking area is ahead","A school is nearby","Passing is not allowed in this zone","A lane ends"],"correct":2},{"id":"q-1b-096","fact_id":"signs-032","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are stuck behind a slow truck and see the pennant sign on the left. What do you do?","options":["Pass if the oncoming lane looks empty","Tailgate closely so the truck speeds up","Pass on a short straight stretch","Stay behind it; no passing here"],"correct":3},{"id":"q-1b-097","fact_id":"signs-036","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows a truck on a steep slope. What does it tell you?","options":["A steep hill is ahead","Trucks must stop here","A truck lane begins","A weigh station is ahead"],"correct":0},{"id":"q-1b-098","fact_id":"signs-036","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You see the steep-hill sign at the top of a long grade. How should you go down?","options":["Drive fast to build momentum","Brake hard all the way down","Coast in neutral to save fuel","Use a low gear to control your speed"],"correct":3},{"id":"q-1b-099","fact_id":"signs-037","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A yellow diamond shows an arrow pointing at a bar over the road, with a height number. What is the warning?","options":["A low bridge or wire is ahead","A weight limit applies","A tall building is ahead","A narrow lane begins"],"correct":0},{"id":"q-1b-100","fact_id":"signs-037","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drive a tall moving van and see the low-clearance sign. You are not sure the van fits. What should you do?","options":["Speed up to pass quickly","Try it slowly","Stop and find another route","Follow the car ahead, since it got through"],"correct":2},{"id":"q-1b-101","fact_id":"signs-038","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"An orange diamond shows a person holding a sign. What does it warn of?","options":["A flagger controls traffic ahead","A traffic signal fault","A school guard","A police stop"],"correct":0},{"id":"q-1b-102","fact_id":"signs-038","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You reach a flagger who holds up a stop sign while the road works are on. The light you passed was green. What do you do?","options":["Slow, then drive on past","Obey the flagger and stop","Go round the flagger","Follow the light and keep driving"],"correct":1},{"id":"q-1b-103","fact_id":"signs-039","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A fluorescent yellow-green diamond shows a bicycle. What does it tell you?","options":["Bicycles must stop here","A bike lane ends","Bicycles are not allowed","Bicycles may cross here"],"correct":3},{"id":"q-1b-104","fact_id":"signs-039","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which pair of signs share the fluorescent yellow-green color?","options":["School crossing and flagger","Bicycle crossing and road work","Pedestrian crossing and railroad crossing","Bicycle crossing and pedestrian crossing"],"correct":3},{"id":"q-2a-001","fact_id":"p14_gaps-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When is it legal to pass another vehicle on its right side?","options":["Only when it is safe, and without leaving the paved road","Whenever the lane on your left is moving slower than you","Any time you can use the shoulder and the shoulder is wide enough","Only on freeways, because city streets never allow it"],"correct":0},{"id":"q-2a-002","fact_id":"p14_gaps-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A car ahead on a two-lane road slows to turn left. Past its right side there is only a dirt strip. What do you do?","options":["Steer onto the dirt strip and drive around its right side","Stay on the pavement and slow down behind it until it moves","Honk, then squeeze past on the right with two wheels on dirt","Speed up and pass on the right before it finishes turning"],"correct":1},{"id":"q-2a-003","fact_id":"p14_gaps-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Two drivers argue. Ana says passing on the right is always illegal. Ben says it is fine if you use the shoulder. Who is right?","options":["Ana, because every right-side pass is a violation","Ben, because the shoulder counts as a lane","Neither: it is allowed only when safe and on the pavement","Both, because it depends on the posted speed limit"],"correct":2},{"id":"q-2a-004","fact_id":"p14_gaps-006","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What should you do about the striped area painted beside a disabled parking space?","options":["Park there if your car is small enough to fit","Use it only for a few minutes if you stay in the car","Leave it empty, because it gives room to get in and out","Park there if you hold a disabled placard"],"correct":2},{"id":"q-2a-005","fact_id":"p14_gaps-006","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"The lot is full. You see a striped patch next to a blue space, with no car in it. You only need two minutes. What is right?","options":["Park in it with your hazard lights on","Park in it, since nobody is using it right now","Park in it, but only if the blue space is empty","Keep looking for another space"],"correct":3},{"id":"q-2a-006","fact_id":"p14_gaps-006","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A blue space has a striped area next to it. Who may park where?","options":["Eligible permit holders in the blue space; nobody in the stripes","Permit holders in both the blue space and the stripes","Anyone in the stripes, but only permit holders in the blue space","Anyone in the blue space for short stops, nobody in the stripes"],"correct":0},{"id":"q-2a-007","fact_id":"p14_gaps-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Traffic is slow. Before you enter an intersection on a green light, what must be true?","options":["The light has only just turned green after a long red","Room is open on the far side for your whole car","Your front bumper can clear the crosswalk","The cars behind you are not honking"],"correct":1},{"id":"q-2a-008","fact_id":"p14_gaps-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You have a green light. Cars are stopped bumper to bumper past the intersection, with space for half your car. What do you do?","options":["Wait before the intersection until there is room","Pull in and stop in the middle, since you have the green","Creep forward so the cars behind stop honking","Move up into the crosswalk and wait there"],"correct":0},{"id":"q-2a-009","fact_id":"p14_gaps-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Many drivers think a green light always means go. Which statement fixes that idea?","options":["Green means go whenever no cross traffic is in sight","Green means go, and you may wait inside the crosswalk if needed","Green means go, but only for the first car in the line","Green means go only if your whole car can clear the far side"],"correct":3},{"id":"q-2a-010","fact_id":"p15_changes-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How close to a crosswalk may you park, where there is no curb extension?","options":["Never closer than 20 feet","Never closer than 10 feet","Never closer than 5 feet","Never closer than 30 feet"],"correct":0},{"id":"q-2a-011","fact_id":"p15_changes-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You want to park next to an intersection. The crosswalk has no paint at all. How far back do you stay?","options":["Right up to the corner, since the crosswalk is not marked","At least 20 feet from where the crosswalk would be","About 10 feet, because only painted lines need more room","At least 15 feet, the same gap as a fire hydrant"],"correct":1},{"id":"q-2a-012","fact_id":"p15_changes-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A curb extension sticks out at a crosswalk. You stop 17 feet back from the crosswalk. What is true?","options":["It is illegal, because the limit is always 20 feet","It is legal, because the limit is 15 feet at a curb extension","It is legal, because the limit is only 10 feet there","It is illegal, because a curb extension needs 25 feet"],"correct":1},{"id":"q-2a-013","fact_id":"p15_changes-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing of parking distances is right?","options":["Crosswalk 20 feet (15 with a curb extension); fire hydrant 15 feet","Crosswalk 15 feet always; fire hydrant 20 feet","Crosswalk 10 feet; fire hydrant 10 feet","Crosswalk 20 feet; fire hydrant needs no distance if the curb is not red"],"correct":0},{"id":"q-2a-014","fact_id":"p15_changes-005","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When did drivers start to get tickets for parking too close to a crosswalk?","options":["On the first day of 2024, with no warning period","In 2025, after a warning period in 2024","In 2026, after two years of warnings","Never; officers can only give warnings"],"correct":1},{"id":"q-2a-015","fact_id":"p15_changes-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"In mid-2024, a parking officer leaves a warning on a car parked 8 feet from a crosswalk. What does that mean?","options":["The rule did not exist yet, so the warning was an error","The driver was not at fault, because warnings cancel the rule","The car was parked wrongly, but fines had not started yet","The driver now owes a ticket by mail"],"correct":2},{"id":"q-2a-016","fact_id":"p15_changes-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Today you park 12 feet before an unmarked crosswalk and leave. Can you get a ticket?","options":["No, a warning period still protects drivers","No, only marked crosswalks bring a ticket","Only if a pedestrian is waiting at that moment","Yes, since tickets for this have been allowed since 2025"],"correct":3},{"id":"q-2a-017","fact_id":"p15_changes-005","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement keeps apart the date the rule began and the date tickets began?","options":["The rule began in 2024 and tickets followed in 2025","The rule began in 2025, and tickets began the same day","Tickets began in 2024, and the rule came a year later","Both began in 2023 under the jaywalking change"],"correct":0},{"id":"q-2a-018","fact_id":"p15_changes-010","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Since 2023, what happens to a pedestrian who safely crosses mid-block, outside a crosswalk?","options":["They get a ticket every time","They get no ticket if the crossing is safe","They get a ticket only after dark","They get a written warning, never a ticket"],"correct":1},{"id":"q-2a-019","fact_id":"p15_changes-010","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You are driving. A pedestrian steps off the curb mid-block, outside any crosswalk. What should you do?","options":["Keep your speed, because they are not in a crosswalk","Honk so they step back onto the curb","Speed up and pass before they reach your lane","Slow down and let them cross"],"correct":3},{"id":"q-2a-020","fact_id":"p15_changes-010","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"After the 2023 change, which statement about crosswalks and mid-block crossings is right?","options":["Mid-block crossing is still a ticket; only crosswalks are legal","A safe mid-block crossing is not ticketed, and drivers must still yield","Mid-block pedestrians have no right to cross, so drivers owe them nothing","Drivers may stop yielding at crosswalks too, since crossing is now free"],"correct":1},{"id":"q-2a-021","fact_id":"s6-28","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Under what condition may you turn right at a red light?","options":["After slowing to a crawl, if the cross street looks empty","Only when a sign says right turns on red are allowed","After a complete stop, unless a sign bans the turn","Only when a green arrow is showing"],"correct":2},{"id":"q-2a-022","fact_id":"s6-28","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait at a red light in the right lane. A No Turn on Red sign is posted and the cross street is empty. What do you do?","options":["Stop fully, then turn right since nothing is coming","Slow down and turn, because the sign only bans fast turns","Signal, then turn right with care","Wait for the green light before you turn"],"correct":3},{"id":"q-2a-023","fact_id":"s6-28","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You come up to a red light with no sign. The road is empty, so you roll through the turn at about 5 mph. What went wrong?","options":["Nothing, since a right turn on red needs no stop","You did not make a complete stop first","You should have waited for a green arrow","You turned right, which is banned at every red light"],"correct":1},{"id":"q-2a-024","fact_id":"s6-29","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"When may you turn left at a red light?","options":["From any street, after a stop, if no cars are near","From one one-way street into another, after a full stop","From the left-turn lane of any two-way street, after a stop","Never; a red light always forbids a left turn"],"correct":1},{"id":"q-2a-025","fact_id":"s6-29","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait in the left-turn lane of a two-way street, turning onto another two-way street. The light is red, nothing is coming and you have stopped. May you turn left?","options":["Yes, since you made a complete stop","Yes, if you yield to anyone already in the crossing","No, wait for a green light or green arrow","Yes, if you turn into the nearest lane"],"correct":2},{"id":"q-2a-026","fact_id":"s6-29","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive on a one-way street that meets another one-way street. The light is red and no sign bans the turn. You stop completely. What may you do?","options":["Turn left when it is clear","Go straight only; turns are never allowed on red","Wait for green, since left turns on red are never allowed","Turn left without stopping, since both streets are one-way"],"correct":0},{"id":"q-2a-027","fact_id":"s6-29","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a red light, which turns are ever allowed after a complete stop?","options":["Right turns only; left turns are never allowed","Left turns anywhere, but right turns only between one-way streets","Both turns anywhere when the road is clear","Right turns; left turns only one-way into one-way"],"correct":3},{"id":"q-2a-028","fact_id":"s6_p11_roadway-001","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At a four-way stop, which vehicle has the right to go first?","options":["The largest vehicle","The vehicle that stopped first","The vehicle that is going straight","The vehicle that arrives with the most speed"],"correct":1},{"id":"q-2a-029","fact_id":"s6_p11_roadway-001","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You stop at a four-way stop. A moment later a car on the cross street stops on your right. Nobody else is there. Who goes first?","options":["The other car, since it is on your right","You do, since you stopped first","Whoever starts to move first","Whoever honks or waves first"],"correct":1},{"id":"q-2a-030","fact_id":"s6_p11_roadway-001","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pair of rules is right for a four-way stop?","options":["The car on the right always goes first, even if it came later","The first car to stop goes first; in a tie the left car yields to the right","The car going straight always goes first, whatever the order","The fastest car goes first; in a tie the right car yields to the left"],"correct":1},{"id":"q-2a-031","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Two cars on adjacent roads stop at a four-way stop at the very same moment. Which one must wait?","options":["The one on the right","The one that is farther from the middle of the crossing","The one on the left","The one on the busier road"],"correct":2},{"id":"q-2a-032","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You head north and reach a four-way stop at the same moment as a car coming from the east, on your right. Who goes first?","options":["You, since you are heading north","You, since you arrived with more speed","Whoever signals first","The car from the east, on your right"],"correct":3},{"id":"q-2a-033","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You head south and reach a four-way stop at the same moment as a car from the east, on your left. Who goes first?","options":["You do, since the other car is on your left","The other car, since it is on a cross street","The other car, since it came from your left","Neither; both stay until a third car comes"],"correct":0},{"id":"q-2a-034","fact_id":"s6_p11_roadway-002","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which statement is right? A: at a four-way stop in a tie, left yields to right. B: at a T-intersection with no signals, who yields?","options":["A is right, and at the T the side street yields to the through road","A is right, and at the T the left car yields to the right car","A is wrong; at both places the first to arrive goes","A is right, and at the T the wider road yields"],"correct":0},{"id":"q-2a-035","fact_id":"s6_p11_roadway-003","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At a T-intersection with no signals, which vehicles have the right of way?","options":["The first car to reach the corner","Vehicles on the road that continues past the T","Vehicles on the street that ends at the T","Vehicles on the road with more lanes"],"correct":1},{"id":"q-2a-036","fact_id":"s6_p11_roadway-003","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You drive along the straight road of a T. A car waits at the end of the side street. You reach the T first. Who goes first?","options":["The waiting car, because it got there first","You do, because your road continues","The car that signals first","You take turns, one car each"],"correct":1},{"id":"q-2a-037","fact_id":"s6_p11_roadway-003","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"At a four-way stop, the order of stopping decides who goes. What decides it at a T with no signals?","options":["The order of arrival, as at the four-way stop","Which car is on the right","Which road continues straight","Which driver has the higher speed"],"correct":2},{"id":"q-2a-038","fact_id":"s6_p11_roadway-004","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"You turn from the side street onto the through road at a T-intersection. Whom must you yield to?","options":["Only the traffic coming from your left","Only vehicles that are close enough to hit you","No one, if you arrived first","All the vehicles on the through road"],"correct":3},{"id":"q-2a-039","fact_id":"s6_p11_roadway-004","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You wait to turn left from a side street at a T. The road is clear on your left, but a car comes from your right. What do you do?","options":["Go, since the left is clear and the right car can slow down","Wait until the car from the right has passed","Go, since you are already at the edge of the intersection","Go, if you signal first"],"correct":1},{"id":"q-2a-040","fact_id":"s6_p11_roadway-004","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Some drivers think a right turn from a side street needs no yielding. At a T with no signals, is that right?","options":["Yes, since right turns are never covered by yield rules","Yes, if you are quicker than the cars on the through road","No, you still yield to the through road, whatever way you turn","No, but only when the through road has more than one lane"],"correct":2},{"id":"q-2a-041","fact_id":"s6_p11_roadway-005","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What must you do at a stop sign?","options":["Slow down and go on if the way is clear","Stop fully only when other vehicles are visible","Stop fully, then look every way before you enter","Stop and look only toward traffic from your left"],"correct":2},{"id":"q-2a-042","fact_id":"s6_p11_roadway-005","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"At night you come to a quiet stop sign. No cars are in sight in any direction. What should you do?","options":["Slow to a walking pace and keep rolling","Make a full stop, look all ways, then go","Skip the stop, because it is late and quiet","Stop only if you hear a car"],"correct":1},{"id":"q-2a-043","fact_id":"s6_p11_roadway-005","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which statement about stop signs and yield signs is right?","options":["A stop sign always needs a full stop; a yield sign only if needed","Both need a full stop, whether or not other cars are near","A yield sign always needs a full stop; a stop sign only when cars are near","Neither sign needs a stop when the road looks clear to you"],"correct":0},{"id":"q-2a-044","fact_id":"s6_p11_roadway-006","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yield sign ask of you?","options":["Come to a full stop every time","Speed up to merge before the other traffic arrives","Give way to vehicles, bicyclists and pedestrians only on the road you enter","Slow down and give way to anyone in your path"],"correct":3},{"id":"q-2a-045","fact_id":"s6_p11_roadway-006","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You approach a yield sign. A cyclist is crossing ahead of you. What do you do?","options":["Slow down, and stop if needed, to let the cyclist go","Keep going, since cyclists must yield to cars","Speed up to pass before the cyclist crosses","Honk so the cyclist stops and lets you through"],"correct":0},{"id":"q-2a-046","fact_id":"s6_p11_roadway-006","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which is true? One sign needs a full stop every time. Another needs only a slow-down and a stop if needed.","options":["Stop: full stop. Yield: slow down and give way","The yield sign needs the full stop; the stop sign needs slowing","Both signs need the same full stop, with no exceptions","Only the stop sign applies to bicyclists and pedestrians in your path"],"correct":0},{"id":"q-2a-047","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Two cars reach an intersection with no signs or signals at the same time. Which must yield?","options":["The one that has the other car on its right","The car that sits on the right of the pair","The car on the smaller of the two streets","The car that is moving at the lower speed"],"correct":0},{"id":"q-2a-048","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You reach a plain residential crossing with no signs. A car arrives from your right at the same moment. What do you do?","options":["Go first, since you are in the left lane","Go first, if you signal","Let the car on your right go first","Go first, since you are faster"],"correct":2},{"id":"q-2a-049","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You reach the same kind of crossing with no signs. A car arrives from your left at the same moment. What do you do?","options":["Wait, since the other car arrived with you","Wait, since cross traffic always goes first","Go ahead, but watch the other car","Stop and wave the other car on"],"correct":2},{"id":"q-2a-050","fact_id":"s6_p11_roadway-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"One car stopped well before the other at a four-way stop. Another pair arrives together at a crossing with no signs. Which is right?","options":["Four-way stop: first to stop goes. No signs: left yields to right","Four-way stop: left yields to right. No signs: first to arrive goes","Both: first to arrive goes","Both: the right car goes, whoever arrived first"],"correct":0},{"id":"q-2a-051","fact_id":"s6_p11_roadway-009","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a steady yellow light tell you to do?","options":["Speed up so that you cross before it turns red","Treat it as a green light for a few more seconds","Cross only if you can do it safely before red; otherwise stop","Stop at once, even if you are already in the intersection"],"correct":2},{"id":"q-2a-052","fact_id":"s6_p11_roadway-009","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are far back from an intersection when the light turns yellow. Plenty of road is left to brake. What do you do?","options":["Brake smoothly and stop before the line","Accelerate, since yellow means go fast","Keep your speed, as a yellow light lasts a long time","Slow a little and cross anyway, because the light is still not red"],"correct":0},{"id":"q-2a-053","fact_id":"s6_p11_roadway-009","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are just at the limit line when the light turns yellow. A hard stop could cause a crash, and you can clear the crossing before red. What is right?","options":["Cross with care, since you can clear it before red","Slam on the brakes, since yellow always means stop","Stop in the middle of the intersection","Wait for the red and then go around"],"correct":0},{"id":"q-2a-054","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yellow arrow signal tell you?","options":["Protected turn time is ending; finish only if already in the crossing","Your protected turn time is just starting, so you may go","You may turn at once without yielding to anyone","The signal is broken and you should treat it as a stop sign"],"correct":0},{"id":"q-2a-055","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You wait at the line for a left turn. The green arrow turns yellow before you have entered. What do you do?","options":["Go quickly through the turn, since the arrow is still lit","Stay behind the line and prepare to stop","Enter and stop at the middle of the crossing","Honk to ask the car ahead to hurry"],"correct":1},{"id":"q-2a-056","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are in the middle of a left turn when the green arrow turns yellow. What do you do?","options":["Stop where you are until the next green","Back up behind the line","Finish the turn","Wait for the car behind you to pass"],"correct":2},{"id":"q-2a-057","fact_id":"s6_p11_roadway-010","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a steady yellow circle differ from a yellow arrow?","options":["They mean the same, since both tell you to stop","The circle ends a protected turn; the arrow warns that red is next","The circle warns that red is next; the arrow ends a protected turn","The arrow means go ahead; the circle means stop"],"correct":2},{"id":"q-2a-058","fact_id":"s6_p11_roadway-012","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What is the smallest gap allowed between a parked car and a crosswalk at an intersection with no curb extension?","options":["Five feet","Ten feet","Twenty feet","Thirty feet"],"correct":2},{"id":"q-2a-059","fact_id":"s6_p11_roadway-012","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You park beside a side-street corner. There is no paint, but the sidewalk ramp shows a crosswalk. You stop 18 feet from it. What is true?","options":["You parked too close; a crosswalk needs 20 feet even unpainted","You are fine, since only crosswalks with paint count for this rule","You are fine, since 18 feet is over the 15-foot rule for crosswalks","You are fine, if you leave the engine running and stay nearby"],"correct":0},{"id":"q-2a-060","fact_id":"s6_p11_roadway-012","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which parking spot breaks the crosswalk rule? Assume no curb extension.","options":["25 feet back from a painted crosswalk at a corner","18 feet back from an unpainted crosswalk at a corner","21 feet back from a painted crosswalk at a corner","30 feet back from an unpainted crosswalk at a corner"],"correct":1},{"id":"q-2a-061","fact_id":"s6_p11_roadway-013","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How near to a fire hydrant may you park?","options":["Within 5 feet only if the curb is red","No closer than 15 feet","No closer than 3 feet","No closer than 20 feet"],"correct":1},{"id":"q-2a-062","fact_id":"s6_p11_roadway-013","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A curb has no paint. A hydrant stands there, and you plan to park 10 feet from it. What is right?","options":["Go ahead, since only a red curb is a no-parking curb","Go ahead, since the hydrant is not in use","Go ahead, since ten feet is beyond the crosswalk rule","Move back, since you must be at least 15 feet away"],"correct":3},{"id":"q-2a-063","fact_id":"s6_p11_roadway-013","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for parking gaps?","options":["Fire hydrant 3 feet; sidewalk ramp 15 feet","Fire hydrant 15 feet; sidewalk ramp 3 feet","Fire hydrant 20 feet; sidewalk ramp 15 feet","Both need 15 feet"],"correct":1},{"id":"q-2a-064","fact_id":"s6_p11_roadway-014","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How near to a fire station driveway may you park?","options":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","As near as you like, if you stay in the car"],"correct":0},{"id":"q-2a-065","fact_id":"s6_p11_roadway-014","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You want to park on the street beside a fire station. The driveway entrance is 8 feet from your spot. What do you do?","options":["Park there, since the driveway is not blocked","Park there, since the station doors are shut","Find a spot at least 15 feet from the entrance","Park there, but leave a note"],"correct":2},{"id":"q-2a-066","fact_id":"s6_p11_roadway-014","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A learner thinks a fire station driveway needs the same 20-foot gap as a crosswalk. What is the real distance?","options":["20 feet, the same as a crosswalk","3 feet, the same as a sidewalk ramp","It depends on the size of the fire trucks","15 feet, the same as a fire hydrant"],"correct":3},{"id":"q-2a-067","fact_id":"s6_p11_roadway-015","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a red curb mean?","options":["No stopping, standing or parking","No parking, but you may stop to load","Parking for a limited time","Emergency vehicles may park, others may stop briefly"],"correct":0},{"id":"q-2a-068","fact_id":"s6_p11_roadway-015","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You need to drop a parcel and will be out of your car for only 30 seconds. The only open curb is red. What do you do?","options":["Stop there with your hazard lights on","Stop there, because it is only 30 seconds","Stop there, if you stay in the driver's seat","Find another place to stop"],"correct":3},{"id":"q-2a-069","fact_id":"s6_p11_roadway-015","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which curb color bans all stopping, standing and parking?","options":["Yellow","Red","White","Green"],"correct":1},{"id":"q-2a-070","fact_id":"s6_p11_roadway-016","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What is a white curb for?","options":["Short passenger pick-up and drop-off","Parking for as long as you like","Loading freight from a truck","Disabled persons with a placard"],"correct":0},{"id":"q-2a-071","fact_id":"s6_p11_roadway-016","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You drop a friend at a white curb. Then you walk into a shop and leave the car for an hour. What is wrong?","options":["Nothing, since the friend got out of the car first","A white curb is for passengers, not for parking","The white curb needs a permit that you lack","You should have used the yellow curb for this stop"],"correct":1},{"id":"q-2a-072","fact_id":"s6_p11_roadway-016","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A white curb and a yellow curb both allow brief stops. How do they differ?","options":["White is for passengers; yellow is for commercial loading","White is for freight; yellow is for passengers","White allows all-day parking; yellow does not","They are the same, so either color works"],"correct":0},{"id":"q-2a-073","fact_id":"s6_p11_roadway-017","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a green curb mean?","options":["Limited-time parking; the limit varies by place","Parking for as long as you like, day or night","A fixed 15-minute limit at every green curb","Loading for commercial trucks and vans only"],"correct":0},{"id":"q-2a-074","fact_id":"s6_p11_roadway-017","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A green curb has a sign that says 30 minutes. You want to park for two hours. What do you do?","options":["Park for two hours, since a green curb is free parking","Park for two hours, since a green curb allows up to 2 hours","Stay no longer than 30 minutes, or go elsewhere","Park for two hours, but move forward once"],"correct":2},{"id":"q-2a-075","fact_id":"s6_p11_roadway-017","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A learner mixes up the green curb and the white curb. Which statement is right?","options":["Green is for passenger drop-off; white is for limited parking","Green is limited-time parking; white is for passenger loading","Both are loading zones for passengers","Both are limited-time parking"],"correct":1},{"id":"q-2a-076","fact_id":"s6_p11_roadway-018","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a yellow curb mean?","options":["Commercial loading, within posted time limits","All-day parking for local residents only","Parking for any driver who pays a meter","No stopping or standing at any time"],"correct":0},{"id":"q-2a-077","fact_id":"s6_p11_roadway-018","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A plumber unloads pipes at a yellow curb. A sign shows a 20-minute limit. How long may the van stay?","options":["As long as the job takes, since work vehicles are exempt","Up to the 20 minutes shown on the sign","All day, if the plumber is working in the building","Only 5 minutes, since the sign is a maximum"],"correct":1},{"id":"q-2a-078","fact_id":"s6_p11_roadway-018","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which is the right match of curb color and use?","options":["Yellow: passenger pick-up; white: commercial loading","Yellow: limited parking; green: commercial loading","Yellow: commercial loading; green: limited parking","Yellow: no stopping; red: commercial loading"],"correct":2},{"id":"q-2a-079","fact_id":"s6_p11_roadway-019","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"Who may park at a blue curb?","options":["Anyone making a short stop of a few minutes","Drivers with a disabled placard or special plates","Anyone who is parking for less than five minutes","Delivery drivers who are loading goods"],"correct":1},{"id":"q-2a-080","fact_id":"s6_p11_roadway-019","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You run into a shop for one minute and find the only free space has a blue curb. You have no placard. What do you do?","options":["Park there for one minute","Park there with your hazard lights on","Park there if no disabled driver is in sight","Find a different space"],"correct":3},{"id":"q-2a-081","fact_id":"s6_p11_roadway-019","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which curb color is reserved for disabled drivers, and which allows loading for passengers?","options":["Blue is for disabled drivers; white is for passenger loading","White is for disabled drivers; blue is for passenger loading","Green is for disabled drivers; white is for loading","Blue is for disabled drivers; yellow is for passenger loading"],"correct":0},{"id":"q-2a-082","fact_id":"s6_p11_roadway-020","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You park facing uphill with no curb. Which way do you turn the front wheels?","options":["To the right, toward the road edge","To the left, toward the road","Straight ahead","It does not matter if the brake is set"],"correct":0},{"id":"q-2a-083","fact_id":"s6_p11_roadway-020","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You park facing uphill on a country road with no curb and set the brake. Why do you also turn the front wheels right?","options":["To make the tires wear more evenly over time","So a rolling car heads for the road edge","So you can pull out faster when you leave later","Because the law only asks for it in rain"],"correct":1},{"id":"q-2a-084","fact_id":"s6_p11_roadway-020","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which setup matches parking uphill with no curb?","options":["Wheels left, toward traffic","Wheels toward the curb, as for downhill with a curb","Wheels straight","Wheels right, toward the road edge"],"correct":3},{"id":"q-2a-085","fact_id":"s6_p11_roadway-021","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"You park facing downhill next to a curb. Which way do you turn the steering wheel?","options":["Away from the curb","Toward the curb","Straight","Either way"],"correct":1},{"id":"q-2a-086","fact_id":"s6_p11_roadway-021","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You park downhill beside a curb, with the brake on. A friend asks what to do with the wheels. What do you say?","options":["Point them toward the curb","Leave them straight, since the brake is set","Point them toward the street","Point them away from the hill"],"correct":0},{"id":"q-2a-087","fact_id":"s6_p11_roadway-021","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which pairing of slope and wheel direction is right when you park beside a curb?","options":["Downhill: toward the curb. Uphill: away from it","Downhill: wheels away from the curb. Uphill: toward it","Both: wheels toward the curb, whatever the slope","Both: wheels straight, with the brake set"],"correct":0},{"id":"q-2a-088","fact_id":"s6_p11_roadway-022","area":"legal_and_liability","type":"recall","difficulty":0.35,"stem":"How close to a wheelchair access ramp at the curb may you park?","options":["Right up against it","No closer than 3 feet","No closer than 15 feet","No closer than 20 feet"],"correct":1},{"id":"q-2a-089","fact_id":"s6_p11_roadway-022","area":"legal_and_liability","type":"situation","difficulty":0.5,"stem":"At a corner, a ramp lets wheelchair users reach the street. You leave one foot between your bumper and the ramp. Is that legal?","options":["No, you must stay at least 3 feet away","Yes, since a foot leaves some space","Yes, since the curb is not painted","Yes, if the ramp is not in use"],"correct":0},{"id":"q-2a-090","fact_id":"s6_p11_roadway-022","area":"legal_and_liability","type":"confusion","difficulty":0.65,"stem":"Which pairing is right for parking gaps near a ramp and a driveway to a fire station?","options":["Ramp 15 feet; station driveway 3 feet","Ramp 3 feet; station driveway 15 feet","Both 3 feet","Both 15 feet"],"correct":1},{"id":"q-2a-091","fact_id":"s6_p11_roadway-027","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"Which step belongs before you start to move into the passing lane?","options":["Signal your plan and check your blind spot","Honk twice and speed up at once","Move over first, then signal the car behind","Turn on your high beams to warn others"],"correct":0},{"id":"q-2a-092","fact_id":"s6_p11_roadway-027","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"A slow truck is ahead. The oncoming lane looks clear. What do you do before you steer into the passing lane?","options":["Steer left, then use the signal while you pass","Signal, check your blind spot, then pull out","Accelerate hard and hope nobody is behind","Flash your lights and begin passing"],"correct":1},{"id":"q-2a-093","fact_id":"s6_p11_roadway-027","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver says: I signal once I'm already in the passing lane. What is the problem?","options":["None, since the signal is optional","The signal belongs before you begin the pass","The signal should be given only after you pass","Passing needs a horn, not a signal"],"correct":1},{"id":"q-2a-094","fact_id":"s6_p11_roadway-029","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"When may you not pass near a crossroad or driveway?","options":["When you cannot see traffic that may approach","When your car is more than 15 years old","Only at night, when seeing is hard","Only when a sign says No Passing is posted"],"correct":0},{"id":"q-2a-095","fact_id":"s6_p11_roadway-029","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are behind a slow car near the top of a hill. A side road joins just ahead and you cannot see it. What do you do?","options":["Pass now, since the other driver will see you","Pass now, if you speed up","Pass now, if you flash your lights","Stay behind until you can see well"],"correct":3},{"id":"q-2a-096","fact_id":"s6_p11_roadway-029","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which place is the safest for a pass?","options":["A crossroad where a hedge hides the side road","A long, straight, open stretch with no side roads","A driveway just past a blind curve ahead","A junction where the view is blocked by a parked truck"],"correct":1},{"id":"q-2a-097","fact_id":"s6_p11_roadway-030","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"How much open road must you have ahead before you start to pass?","options":["A few car lengths past the vehicle you pass","Enough to finish and return to your lane safely","Whatever you can see at the moment you pull out","Enough to reach the speed limit while passing"],"correct":1},{"id":"q-2a-098","fact_id":"s6_p11_roadway-030","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You follow a slow van on a winding hill road. You can see only a short way past the next curve. What do you do?","options":["Pass now, since the lane looks empty at this moment","Stay behind until a long, clear stretch appears","Pass and speed up, to get back before the curve","Pass if the van signals that it will slow"],"correct":1},{"id":"q-2a-099","fact_id":"s6_p11_roadway-030","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"A driver checks that the opposite lane is empty as she pulls out to pass. What did she forget?","options":["To check that it stays clear long enough to finish the pass","To check that the car ahead has a green light","To check her fuel level before she starts","To check that the road is wide enough for three cars"],"correct":0},{"id":"q-2a-100","fact_id":"s6_p11_roadway-031","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"You have passed a vehicle. What do you do before you move back to your lane?","options":["Move back first and signal a moment after","Signal, then return once you are clear","Honk once instead of using a signal","Nothing, since the other driver can see you"],"correct":1},{"id":"q-2a-101","fact_id":"s6_p11_roadway-031","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You have just passed a truck. You can see its front bumper in your mirror. What is the next step?","options":["Cut back at once, since you are ahead","Signal to move back, then return smoothly","Brake hard to make room","Stay in the passing lane for several miles"],"correct":1},{"id":"q-2a-102","fact_id":"s6_p11_roadway-031","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"Which describes the signals in a pass?","options":["Signal once at the start, and not again","Signal only when you return to your lane","Signal to pull out, and again to return","No signals are needed if nobody is behind you"],"correct":2},{"id":"q-2a-103","fact_id":"s6_p11_roadway-032","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"Which crosswalks give pedestrians the right of way?","options":["Only crosswalks with painted lines","Marked and unmarked crosswalks alike","Only crosswalks with a traffic signal","Only crosswalks near a school"],"correct":1},{"id":"q-2a-104","fact_id":"s6_p11_roadway-032","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You approach a quiet corner with no paint on the road. A pedestrian steps off the curb to cross. What do you do?","options":["Go on, since there is no marked crosswalk","Speed up to pass before they reach the road","Stop and let them cross","Honk and wave them back"],"correct":2},{"id":"q-2a-105","fact_id":"s6_p11_roadway-032","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"A friend says only painted crosswalks protect pedestrians. What is wrong with that?","options":["Nothing; paint is what creates the right of way","Unmarked crosswalks protect pedestrians too","Only crosswalks with lights protect pedestrians","Pedestrians have the right of way everywhere on the road"],"correct":1},{"id":"q-2a-106","fact_id":"s6_p11_roadway-033","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"A vehicle is stopped at a crosswalk. Why must you not pass it?","options":["It may be stopping for a hidden pedestrian","Its driver might be lost or checking a map","Passing is allowed only on the right","It will pull away faster than you"],"correct":0},{"id":"q-2a-107","fact_id":"s6_p11_roadway-033","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You drive in the left lane. A car in the next lane stops short of a crosswalk. The road ahead looks clear. What do you do?","options":["Go past it, since your lane is clear","Hold back and check for pedestrians","Honk so the car moves on out of the way","Go past it slowly with your window open"],"correct":1},{"id":"q-2a-108","fact_id":"s6_p11_roadway-033","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"The driver of a car stopped at a crosswalk waves you around. What is the right call?","options":["Go around, since the driver told you it was fine","Go around, if you slow down first","Go around, but only on the right","Stay behind; you still cannot see the crosswalk"],"correct":3},{"id":"q-2a-109","fact_id":"s6_p11_run2-017","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"What should you do as you enter a roundabout?","options":["Come to a full stop at the entrance every time","Slow down and yield to traffic in the circle","Speed up to merge with the circle","Enter first if you are going straight on"],"correct":1},{"id":"q-2a-110","fact_id":"s6_p11_run2-017","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You come up to a roundabout. A car is already circling and about to pass your entry. What do you do?","options":["Enter and trust the circling car to slow down","Speed up to enter ahead of the circling car","Wait at the entry until it has passed","Flash your lights and enter at once"],"correct":2},{"id":"q-2a-111","fact_id":"s6_p11_run2-017","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How does a roundabout entry differ from a stop sign?","options":["A roundabout: slow down and yield. A stop sign: full stop","Both need a full stop each time you arrive","A roundabout needs a full stop; a stop sign only a slow-down","Neither one needs you to give way to anyone at all"],"correct":0},{"id":"q-2a-112","fact_id":"s6_p11_run2-018","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"When you leave a roundabout, what should you do with your signal?","options":["Signal in advance of your exit","Signal after you have left the circle","Use no signal, since all traffic goes the same way","Flash your lights instead of signaling"],"correct":0},{"id":"q-2a-113","fact_id":"s6_p11_run2-018","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You are in a roundabout and your exit is the next one. A car waits at that entry. What do you do?","options":["Signal before your exit so the waiting driver knows","Leave without signaling, since the driver can see your path","Brake hard at the exit and then signal","Wave at the waiting driver"],"correct":0},{"id":"q-2a-114","fact_id":"s6_p11_run2-018","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"A learner says signals are pointless in a circle since everyone drives the same way. What is wrong with that?","options":["Nothing; drivers can read your path from the circle","Signals are only needed on entry","Signals are needed to show where you will leave","Signals are needed only at night"],"correct":2},{"id":"q-2a-115","fact_id":"s6_p11_run2-026","area":"driving_safety","type":"recall","difficulty":0.35,"stem":"What can happen if you turn from the wrong lane?","options":["Nothing, if you signal early enough","A violation, and a risk to other drivers","It is legal if nobody is behind you","A fine, but only on roads with three lanes or more"],"correct":1},{"id":"q-2a-116","fact_id":"s6_p11_run2-026","area":"driving_safety","type":"situation","difficulty":0.5,"stem":"You are in the middle lane of three when you notice your turn. You sit in the lane next to the one you need. What do you do?","options":["Cut across two lanes and turn from the edge","Turn from where you are, since the way is clear","Go on to the next turn and change lane in good time","Honk and turn from the wrong lane"],"correct":2},{"id":"q-2a-117","fact_id":"s6_p11_run2-026","area":"driving_safety","type":"confusion","difficulty":0.65,"stem":"Which is the real risk of a turn from an incorrect lane?","options":["Only a few seconds lost at the next light","It can cut across a driver's path in the right lane","It can damage the tires on the curb as you turn","It only matters on roads with two lanes"],"correct":1},{"id":"q-2a-118","fact_id":"s6_p11_run2-027","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"At an intersection with several lanes, from which lane do you make a left turn?","options":["The left lane","The right lane","Any lane that has no cars","The middle lane only"],"correct":0},{"id":"q-2a-119","fact_id":"s6_p11_run2-027","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"You plan a right turn at the next corner but you are in the left lane. The right lane looks emptier. What do you do?","options":["Turn right from the left lane to save time","Move to the right lane in good time, then turn","Wait until the corner and then cut across","Stop in the left lane until traffic clears"],"correct":1},{"id":"q-2a-120","fact_id":"s6_p11_run2-027","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which pairing of turn and lane is right?","options":["Right turn from the left lane; left turn from the right lane","Both turns from the middle lane","Right turn from the right lane; left turn from the left lane","Either lane for either turn when it is empty"],"correct":2},{"id":"q-2a-121","fact_id":"s6_p11_run3-005","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How is a two-way left-turn lane marked?","options":["Solid yellow outside, dashed yellow inside","Two solid white lines on both sides","Dashed white lines on the outside, solid on the inside","A single dashed yellow line down the center"],"correct":0},{"id":"q-2a-122","fact_id":"s6_p11_run3-005","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"A lane in the middle of a road has a solid yellow line on each outer side and a dashed yellow line on each inner side. What is it for?","options":["Passing slower cars","Left turns from either direction","Parking for deliveries","A lane for emergency vehicles only"],"correct":1},{"id":"q-2a-123","fact_id":"s6_p11_run3-005","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which marking shows a left-turn lane, not a no-passing zone?","options":["Two solid yellow lines side by side","A solid yellow line with a dashed line on the outside","A single broken white line down the middle","Dashed yellow inside, solid yellow outside"],"correct":3},{"id":"q-2a-124","fact_id":"s6_p11_run3-006","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How far may you drive in a two-way left-turn lane while you prepare for the turn?","options":["No more than 200 feet","No more than 50 feet","No more than 500 feet","As far as you like, if the lane is empty"],"correct":0},{"id":"q-2a-125","fact_id":"s6_p11_run3-006","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"Your driveway is a quarter mile ahead. You enter the center turn lane now so you can skip the traffic. What is wrong?","options":["Nothing, since the lane is open to all","You are staying in the lane too far","You need to drive on the shoulder instead","You need a permit for the lane"],"correct":1},{"id":"q-2a-126","fact_id":"s6_p11_run3-006","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"Which use of a center turn lane is right?","options":["Pass a slow car by using it as a passing lane","Drive in it for a mile to avoid a slow queue","Wait in it a few hundred feet to turn left","Enter it close to your turn and leave it within 200 feet"],"correct":3},{"id":"q-2a-127","fact_id":"s6_p11_run3-007","area":"roadway_rules","type":"recall","difficulty":0.35,"stem":"How do you treat a flashing red traffic light?","options":["Slow down and go on if the road is clear","Stop fully first, as at a stop sign","Treat it as a yield sign and roll through","Treat it as a flashing yellow and slow down"],"correct":1},{"id":"q-2a-128","fact_id":"s6_p11_run3-007","area":"roadway_rules","type":"situation","difficulty":0.5,"stem":"At night you reach a signal that is flashing red in all directions. No cars are in sight. What do you do?","options":["Slow down to a walking pace and go on","Stop fully, look all ways, then go","Go on at speed, since the road is empty","Wait until it changes to green"],"correct":1},{"id":"q-2a-129","fact_id":"s6_p11_run3-007","area":"roadway_rules","type":"confusion","difficulty":0.65,"stem":"How do a flashing red and a flashing yellow light differ?","options":["Red: full stop. Yellow: slow and take care","Flashing red: slow down; flashing yellow: full stop","Both need a full stop before you go on","Both mean the signal is out of order"],"correct":0},{"id":"q-2a-130","fact_id":"s7-15","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"What does a flashing yellow arrow pointing left mean?","options":["You may turn left after yielding to oncoming traffic","You have a protected left turn with no oncoming traffic","You must stop and wait for the next green light","You may turn left only if you are first in line"],"correct":0},{"id":"q-2a-131","fact_id":"s7-15","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"You wait at a light with a flashing yellow left arrow. A car is coming straight toward you. What do you do?","options":["Turn left at once, since you have the arrow","Wait for the oncoming car to pass, then turn","Speed up and turn before it gets to you","Flash your lights at the oncoming car"],"correct":1},{"id":"q-2a-132","fact_id":"s7-15","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How does a flashing yellow left arrow differ from a steady green left arrow?","options":["Flashing yellow: protected turn; green arrow: yield first","Flashing: yield first. Green arrow: protected","Both are protected turns with no yielding","Both are a signal to stop and wait for green"],"correct":1},{"id":"q-2a-133","fact_id":"s7-16","area":"signs_and_signals","type":"recall","difficulty":0.35,"stem":"A traffic signal is completely dark. How do you treat the crossing?","options":["Like a four-way stop","Like a yield sign for the busier road","Like an open road, since no signal shows","Like a flashing yellow, slowing only"],"correct":0},{"id":"q-2a-134","fact_id":"s7-16","area":"signs_and_signals","type":"situation","difficulty":0.5,"stem":"A power cut turns off the signal at a crossing. You stop, and a car on the cross street stops at the same moment on your right. What do you do?","options":["Go first, since you are on the bigger road","Let the car on your right go first","Go through together, since no signal is working","Wait for a police officer before moving"],"correct":1},{"id":"q-2a-135","fact_id":"s7-16","area":"signs_and_signals","type":"confusion","difficulty":0.65,"stem":"How should you treat a dark signal compared with a flashing yellow signal?","options":["Dark: stop everywhere. Flashing yellow: take care","Both: go on through without any stop at all","Dark: go on with care; flashing yellow: stop","Both: stop and wait for the signal to work"],"correct":0}]`),i={tag:e,batches:t,blueprint:a,questions:o};export{t as batches,a as blueprint,i as default,o as questions,e as tag};
